{
  "name": "pairwise_cost_gap_loss",
  "intuition": "This loss encourages the model to assign higher log probabilities to better-performing sequences by using cost gaps, which measure the difference between the top choice and others. Minimizing the negative log sigmoid of the cost gap aligns higher probability with lower cost, effectively promoting preference consistency.",
  "pseudocode": "loss = mean over pairs of ( -logsigmoid( (log_prob_w - log_prob_l) * cost_gap ) )",
  "hyperparams": {
    "paradigm_family": "pairwise_comparison",
    "signal_family": "cost_gap_signal",
    "link_family": "sigmoid_link",
    "agg_family": "mean_aggregation",
    "constraint_family": "none",
    "other_hparams": "None"
  },
  "operators_used": ["logsigmoid", "sub", "mul", "mean"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    log_prob_w = batch['log_prob_w']\n    log_prob_l = batch['log_prob_l']\n    cost_gap = batch['cost_gap']\n    weight = batch['weight']\n    scores = ops.mul(cost_gap, ops.sub(log_prob_w, log_prob_l))\n    loss_terms = ops.neg(ops.logsigmoid(scores))\n    weighted_loss = ops.mul(loss_terms, weight)\n    return ops.mean(weighted_loss)"
}

{
  "name": "loss_margin_consistency_advantage",
  "intuition": "enforce consistency by penalizing margin disagreement weighted by advantage difference, linking margin and advantage signals with a sigmoid-based penalty aggregated by mean",
  "pseudocode": "margin = log_prob_w - log_prob_l\nadv_diff = advantage_w - advantage_l\npenalty = sigmoid(-margin * adv_diff)\nloss = mean(weight * penalty)",
  "hyperparams": {
    "paradigm_family": "pairwise_consistency",
    "signal_family": "advantage_gap",
    "link_family": "sigmoid",
    "agg_family": "mean",
    "constraint_family": "none"
  },
  "operators_used": ["sigmoid", "mul", "sub", "mean"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', ops.ones_like(lpw))\n    adv_w = batch['advantage_w']\n    adv_l = batch['advantage_l']\n    margin = ops.sub(lpw, lpl)\n    adv_diff = ops.sub(adv_w, adv_l)\n    penalty = ops.sigmoid(ops.neg(ops.mul(margin, adv_diff)))\n    loss = ops.mul(penalty, weight)\n    return ops.mean(loss)"
}

