{
  "name": "loss_logsigmoid_001_cost_logsumexp_stabilized",
  "intuition": "Simplified the loss by explicitly implementing the log-sum-exp trick for numerical stability and normalizing the loss by the number of pairs. Clamped the margin term to [-20, 20] to avoid numerical instability in logsigmoid. Incorporated weight if present without changing semantics. Used only 'cost_a' and 'cost_b' for a stable cost gap signal, detaching it to avoid gradient issues.",
  "hyperparams": {
    "scale": "1.9496803035382082",
    "paradigm_family": "pairwise_margin",
    "signal_family": "cost_gap",
    "link_family": "logsigmoid",
    "agg_family": "logsumexp",
    "constraint_family": "clamp_stabilized"
  },
  "implementation_hint": {
    "mode": "pairwise",
    "expects": [
      "log_prob_w",
      "log_prob_l",
      "weight",
      "cost_a",
      "cost_b"
    ]
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.0)))\n    scale = float(extra.get('hyperparams', {}).get('scale', 1.9496803035382082))\n    cost_a = batch['cost_a']\n    cost_b = batch['cost_b']\n    gap = (cost_b - cost_a).detach()\n    gap_coef = 0.1\n    margin = alpha * scale * (lpw - lpl) - gap_coef * gap\n    margin_clamped = ops.clamp(margin, -20.0, 20.0)\n    per_pair_loss = -ops.logsigmoid(margin_clamped)\n    if weight is not None:\n        per_pair_loss = per_pair_loss * weight\n    max_loss = per_pair_loss.max()\n    exp_shifted = ops.exp(per_pair_loss - max_loss)\n    sum_exp = ops.sum(exp_shifted)\n    logsumexp = max_loss + ops.log(sum_exp)\n    count = per_pair_loss.shape[0] if per_pair_loss.ndim > 0 else 1\n    loss = logsumexp - ops.log(ops.ones_like(max_loss) * count)\n    return loss"
}

{
  "name": "pairwise_preference_signal",
  "intuition": "This loss models preferences by encouraging the model to assign higher log probability to preferred options. Using the advantage signal (advantage_w - advantage_l) scaled by a cost gap ensures the model learns to prefer lower-cost options with higher advantage, aligning preferences with rewards and constraints. It effectively penalizes undesirable pairs and promotes better choices.",
  "pseudocode": "score = (log_prob_w - log_prob_l) * (advantage_w - advantage_l) - alpha * cost_gap\\nloss = mean(max(0, -score))",
  "hyperparams": {
    "paradigm_family": "preference",
    "signal_family": "advantage",
    "link_family": "pairwise",
    "agg_family": "mean",
    "constraint_family": "cost"
  },
  "operators_used": ["logsigmoid", "sub", "mul", "max", "mean", "sub"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\\n    alpha = float(extra.get(\"alpha\", 1.0))\\n    log_prob_w = batch[\"log_prob_w\"]\\n    log_prob_l = batch[\"log_prob_l\"]\\n    advantage_w = batch.get(\"advantage_w\", ops.zeros_like(log_prob_w))\\n    advantage_l = batch.get(\"advantage_l\", ops.zeros_like(log_prob_l))\\n    cost_gap = batch[\"cost_gap\"]\\n    score = ops.sub(ops.sub(log_prob_w, log_prob_l), ops.mul(alpha, cost_gap))\\n    advantage_diff = ops.sub(advantage_w, advantage_l)\\n    preference_score = ops.mul(score, advantage_diff)\\n    loss = ops.mean(ops.maximum(ops.neg(preference_score), ops.zeros_like(preference_score)))\\n    return loss"
}

{
  "name": "pairwise_pref_score",
  "intuition": "This loss compares pairwise log probabilities weighted by a preference signal, such as cost gap, encouraging the model to assign higher probability to better options. Using logsigmoid on the difference captures the preference with smooth gradients, emphasizing pairs where the cost gap is significant.",
  "pseudocode": "loss = mean over pairs of logsigmoid(log_prob_w - log_prob_l + alpha * cost_gap)",
  "hyperparams": {
    "paradigm_family": "preference",
    "signal_family": "cost",
    "link_family": "logsigmoid",
    "agg_family": "pairwise",
    "constraint_family": "monotonic"
  },
  "operators_used": ["logsigmoid"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    log_prob_w = batch['log_prob_w']\n    log_prob_l = batch['log_prob_l']\n    weight = batch['weight']\n    cost_gap = batch['cost_gap']\n    score_diff = ops.sub(log_prob_w, log_prob_l)\n    preference_signal = ops.mul(ops.sign(cost_gap), extra.get('alpha', 1.0))\n    scaled_diff = ops.add(score_diff, preference_signal)\n    loss_per_pair = ops.logsigmoid(scaled_diff)\n    weighted_loss = ops.mul(loss_per_pair, weight)\n    mean_loss = ops.mean(weighted_loss)\n    return mean_loss"
}

{
  "name": "loss_logsigmoid_001_normalized",
  "intuition": "Adds explicit normalization by dividing the weighted loss sum by total weight, ensuring scale invariance of the loss with respect to weights.",
  "pseudocode": "normalized_loss = sum(weight * -logsigmoid(clamp(alpha*scale*(lpw - lpl), -20, 20))) / sum(weight)",
  "hyperparams": {
    "paradigm_family": "pairwise_margin",
    "signal_family": "logprob_gap",
    "link_family": "logsigmoid",
    "agg_family": "weighted_mean",
    "constraint_family": "normalization_invariant"
  },
  "operators_used": ["logsigmoid", "clamp", "mul", "div", "sum"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.0)))\n    scale = float(extra.get('hyperparams', {}).get('scale', 0.6752757766189963))\n    x = alpha * scale * (lpw - lpl)\n    x = ops.clamp(x, -20.0, 20.0)\n    loss = -ops.logsigmoid(x)\n    if weight is not None:\n        weighted_loss = loss * weight\n        total_weight = ops.sum(weight)\n        normalized_loss = ops.sum(weighted_loss) / (total_weight + 1e-12)\n        return normalized_loss\n    else:\n        return loss.mean()"
}

{
  "name": "loss_tanh_advantage_weighted_margin_repaired",
  "intuition": "Applies a smooth tanh and relu transformation on margin weighted by advantage_gap; clamps advantage_gap to avoid zero gradients and clamps inputs to stable ranges.",
  "pseudocode": "margin = lpw - lpl\nclamped_adv_gap = clamp(advantage_gap, min=eps)\nweighted_margin = margin * clamped_adv_gap\nloss = mean(weight * beta * relu(tanh(alpha * weighted_margin)))",
  "hyperparams": {
    "paradigm_family": "pairwise_margin_smooth",
    "signal_family": "advantage_gap",
    "link_family": "tanh_relu",
    "agg_family": "mean",
    "constraint_family": "none"
  },
  "operators_used": ["sub", "mul", "tanh", "relu", "mean", "clamp"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    eps = 1e-8\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', lpw.new_ones(lpw.shape))\n    advantage_gap = batch['advantage_gap']\n    alpha = float(extra.get('alpha', 1.0))\n    beta = float(extra.get('beta', 1.0))\n    clamped_adv_gap = ops.clamp(advantage_gap, min=eps)\n    margin = ops.sub(lpw, lpl)\n    weighted_margin = ops.mul(margin, clamped_adv_gap)\n    transformed = ops.relu(ops.tanh(ops.mul(alpha, ops.clamp(weighted_margin, min=-100.0, max=100.0))))\n    loss = ops.mul(beta, transformed)\n    loss = ops.mul(loss, weight)\n    return ops.mean(loss)"
}
